#!/bin/bash\n\n# Sign and Align APK\n\necho \"🔑 Signing and Aligning APK...\"\n\nAPK_UNSIGNED=\"cordova-app/platforms/android/app/build/outputs/apk/release/app-release-unsigned.apk\"\nKEYSTORE=\"animehub.keystore\"\nKEY_ALIAS=\"animehub\"\nOUTPUT_APK=\"app-release-signed.apk\"\nALIGNED_APK=\"app-release-aligned.apk\"\n\n# Check if keystore exists\nif [ ! -f \"$KEYSTORE\" ]; then\n    echo \"🔐 Creating new keystore...\"\n    keytool -genkey -v -keystore \"$KEYSTORE\" -keyalg RSA -keysize 2048 -validity 10000 -alias \"$KEY_ALIAS\"\nfi\n\n# Sign the APK\necho \"✍️  Signing APK...\"\njarsigner -verbose -sigalg SHA256withRSA -digestalg SHA-256 \\\n  -keystore \"$KEYSTORE\" \\\n  \"$APK_UNSIGNED\" \\\n  \"$KEY_ALIAS\"\n\nif [ $? -eq 0 ]; then\n    echo \"✅ APK signed successfully!\"\nelse\n    echo \"❌ Signing failed!\"\n    exit 1\nfi\n\n# Rename unsigned to signed\nmv \"$APK_UNSIGNED\" \"$OUTPUT_APK\"\n\n# Find and run zipalign\necho \"📐 Aligning APK...\"\n\n# Try to find zipalign\nZIPALIGN=$(find $ANDROID_SDK_ROOT/build-tools -name \"zipalign\" 2>/dev/null | head -1)\n\nif [ -z \"$ZIPALIGN\" ]; then\n    # Try alternative paths\n    if [ -f \"$ANDROID_HOME/build-tools/33.0.0/zipalign\" ]; then\n        ZIPALIGN=\"$ANDROID_HOME/build-tools/33.0.0/zipalign\"\n    elif [ -f \"$HOME/Android/Sdk/build-tools/33.0.0/zipalign\" ]; then\n        ZIPALIGN=\"$HOME/Android/Sdk/build-tools/33.0.0/zipalign\"\n    else\n        echo \"⚠️  zipalign not found. Skipping alignment.\"\n        ZIPALIGN=\"\"\n    fi\nfi\n\nif [ -n \"$ZIPALIGN\" ]; then\n    \"$ZIPALIGN\" -v 4 \"$OUTPUT_APK\" \"$ALIGNED_APK\"\n    \n    if [ $? -eq 0 ]; then\n        rm \"$OUTPUT_APK\"\n        mv \"$ALIGNED_APK\" \"$OUTPUT_APK\"\n        echo \"✅ APK aligned successfully!\"\n    fi\nfi\n\necho \"\"\necho \"🎉 APK signing complete!\"\necho \"📦 Final APK: $OUTPUT_APK\"\necho \"\"\necho \"📊 APK Info:\"\nls -lh \"$OUTPUT_APK\"\necho \"\"\necho \"🚀 To install on device:\"\necho \"   adb install $OUTPUT_APK\"\necho \"\"\necho \"📤 To upload to Google Play:\"\necho \"   1. Go to Google Play Console\"\necho \"   2. Create new release\"\necho \"   3. Upload $OUTPUT_APK\"\n